<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { api } from './api'
import WorkspaceDialog from './WorkspaceDialog.vue'
import DirectoryBrowser from './DirectoryBrowser.vue'
const props=defineProps<{profile:any}>()
const open=ref(false),busy=ref(false),error=ref(''),notice=ref(''),state=ref<any>(null),draft=ref<Record<string,any>>({}),preview=ref<Record<string,any>>({}),dirty=ref<Record<string,boolean>>({}),active=ref('concurrency_cases.md'),picker=ref(false)
const names=[['concurrency_cases.md','并发案例库'],['review_context.md','当前工程背景']]
const current=computed(()=>draft.value[active.value]),info=computed(()=>preview.value[active.value]),title=computed(()=>names.find(x=>x[0]===active.value)?.[1])
let generation=0
watch(()=>props.profile?.id+'|'+props.profile?.revision,()=>{generation++;open.value=false;state.value=null})
function adopt(value:any){state.value=value;preview.value=value.documents;draft.value=Object.fromEntries(Object.entries<any>(value.documents).map(([name,d])=>[name,{mode:d.mode,path:d.configured_path||d.path||'',sha256:d.sha256,content:d.text||''}]));dirty.value={}}
async function show(){if(!props.profile)return;const mine=++generation;open.value=true;busy.value=true;error.value='';notice.value='';try{const value=await api(`/profiles/${props.profile.project_id}/${props.profile.id}/review-materials`);if(mine===generation)adopt(value)}catch(e:any){if(mine===generation)error.value=e.message}finally{if(mine===generation)busy.value=false}}
async function read(){busy.value=true;error.value='';try{const name=active.value,value=await api(`/profiles/${props.profile.project_id}/${props.profile.id}/review-materials/preview`,'POST',{name,source:current.value});preview.value={...preview.value,[name]:value};if(value.available&&value.editable)draft.value[name].content=value.text;dirty.value[name]=false}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';try{const value=await api(`/profiles/${props.profile.project_id}/${props.profile.id}/review-materials`,'POST',{profile_revision:props.profile.revision,revision:state.value.revision,documents:draft.value});adopt(value);notice.value='资料已保存。新复核任务会使用此来源；已启动或恢复任务保持原冻结版本。'}catch(e:any){error.value=e.message}finally{busy.value=false}}
function changed(){dirty.value[active.value]=true;notice.value=''}
function selected(value:{path:string}){current.value.mode='file';current.value.path=value.path;picker.value=false;changed()}
function close(){if(busy.value)return;open.value=false;generation++}
defineExpose({show})
</script>
<template><section class="review-materials"><button type="button" :disabled="!profile" @click="show">案例库与工程背景</button><p v-if="!profile" class="muted">保存当前工程配置后，可为它选择或编辑这两份复核资料。</p><WorkspaceDialog v-if="open" title="案例库与工程背景" :error="error" @close="close"><p><strong>{{profile.name||profile.id}}</strong> · 随当前工程配置独立保存。默认沿用原相邻文件；没有时读取工具 config。关闭窗口不会保存草稿。</p><div class="section-tabs" role="tablist" aria-label="复核资料分组"><button v-for="[name,label] in names" type="button" role="tab" :disabled="busy" :aria-selected="active===name" @click="active=name">{{label}}</button></div><p v-if="notice" role="status" class="banner">{{notice}}</p><p v-if="busy" role="status">正在读取或保存完整资料…</p><template v-if="current"><label>资料来源<select aria-label="复核资料来源" v-model="current.mode" :disabled="busy" @change="changed"><option value="automatic">沿用原相邻文件，或工具 config 默认</option><option value="builtin">工具 config 中的原文件</option><option value="file">读取本机文件 · 每次复核使用最新保存内容</option><option value="managed" :disabled="info?.preview_only">编辑工程副本 · 不修改工具原文件</option><option v-if="active==='review_context.md'" value="empty">不提供额外工程背景</option></select></label><div v-if="current.mode==='file'" class="material-path"><label>Markdown 文件绝对路径<input aria-label="复核资料文件路径" v-model="current.path" :disabled="busy" @input="changed"/></label><button :disabled="busy" @click="picker=true">选择资料文件</button></div><p v-if="current.mode==='file'" class="muted">本机文件会在每轮重新读取；换电脑时请重新选择路径，或改存“编辑工程副本”以随数据搬迁。</p><p class="muted">案例库帮助识别风险模式，不能代替当前源码证据；工程背景是用户声明，仍须由复核核实。只填写当前工程适用的信息。</p><p v-if="dirty[active]&&current.mode!=='managed'" class="banner warning">来源已更改，请读取预览核对；保存时也会再次验证实际来源。</p><button v-if="current.mode!=='managed'" :disabled="busy" @click="read">读取所选来源预览</button><template v-if="info"><p v-if="!info.available" role="alert" class="banner error">无法读取：{{info.error}}。请修复路径或改用工具 config 文件。</p><template v-else><p class="material-source">{{info.path||'无额外工程背景'}} · {{info.bytes}} 字节<span v-if="info.cases!==undefined"> · 已识别 {{info.cases}} 条案例</span><span v-if="info.effective_chars!==undefined"> · 生效工程背景 {{info.effective_chars}} 字符</span></p><p v-if="info.notice" class="banner warning">{{info.notice}}</p><details><summary>完整内容哈希与格式提示</summary><p class="identity">SHA-256 {{info.sha256||'空背景'}}</p><p v-for="warning in info.warnings">{{warning}}</p></details></template></template><label v-if="current.mode==='managed'">{{title}}正文<textarea :aria-label="title+'正文'" v-model="current.content" :disabled="busy" rows="15" spellcheck="false" @input="changed"/></label><details v-else-if="info?.available&&current.mode!=='empty'" class="material-preview"><summary>查看{{info.preview_only?'预览':'完整'}}正文 · 切换“编辑工程副本”可修改</summary><pre>{{info.text}}</pre></details><p v-if="current.mode==='managed'" class="muted">保存为当前工程配置的独立副本；案例可按 CASE 标题追加，工程背景中的HTML模板注释不会送入复核。</p></template><template #footer><span>正式复核在任务启动时冻结内容并记录哈希。</span><div class="actions"><button :disabled="busy" @click="close">关闭</button><button class="primary" :disabled="busy||!state" @click="save">保存复核资料</button></div></template></WorkspaceDialog><DirectoryBrowser v-if="picker" title="选择复核资料文件" kind="review_document" :start="current?.path||profile?.project_root||''" @selected="selected" @close="picker=false"/></section></template>
<style scoped>.review-materials{margin-top:12px}.review-materials>.muted{font-size:12px}.material-path{display:flex;align-items:flex-end;gap:8px}.material-path label{flex:1;min-width:0;margin:0}.material-path button{flex-shrink:0}.material-source{font-size:13px;overflow-wrap:anywhere}.material-preview pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}.workspace-dialog textarea{font-size:14px;line-height:1.5;min-height:280px}</style>
